local function New(c,p,par) local o=Instance.new(c) if p then for k,v in pairs(p) do pcall(function() o[k]=v end) end end if par then o.Parent=par end return o end

local STAGE_POS = V3(2251.1474609375, 77.302734375, -752.056396484375)
_G.TweenSpeed = 16

local RarityList = {}
pcall(function() local d=require(Rep.src.GameConfiguration.General.rarityColors) for k,_ in pairs(d) do table.insert(RarityList,k) end end)
if #RarityList==0 then RarityList={"Common","Uncommon","Rare","Epic","Legendary"} end

local IslandList = {}
local function Contains(t, v) for _,x in ipairs(t) do if x==v then return true end end return false end
pcall(function()
    if workspace:FindFirstChild("Structures") and workspace.Structures:FindFirstChild("Islands") then
        for _,v in ipairs(workspace.Structures.Islands:GetChildren()) do if not Contains(IslandList, v.Name) then table.insert(IslandList,v.Name) end end
    end
    if workspace:FindFirstChild("HalloweenDimension") and workspace.HalloweenDimension:FindFirstChild("Islands") then
        for _,v in ipairs(workspace.HalloweenDimension.Islands:GetChildren()) do if not Contains(IslandList, v.Name) then table.insert(IslandList,v.Name) end end
    end
end)
if #IslandList==0 then IslandList={"Starter"} end

local SelectedRarities, SelectedArea, StealMode = {}, {IslandList[1]}, "Normal"
local AutoSteal = false
local OldNamecall, OldInvoke, AntiGuardEnabled = nil, nil, false
local GuardRF = nil
pcall(function() GuardRF = Rep.src.Packages._Index["sleitnick_knit@1.7.0"].knit.Services.GuardService.RF.Capture end)

local function GetHRP() return plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") end
local function IsDropOn()
    local gen = plr.PlayerGui:FindFirstChild("General")
    local btn = gen and gen:FindFirstChild("DropButton", true)
    return btn and btn.Visible or false
end
local function FireInteract(m) for _,v in ipairs(m:GetDescendants()) do if v:IsA("ProximityPrompt") then pcall(function() fireproximityprompt(v) end) end end end

local function GetEggFolder(areaName)
    local se = workspace:FindFirstChild("SpawnedEggs")
    if se and se:FindFirstChild(areaName) then return se:FindFirstChild(areaName) end
    local hSe = workspace:FindFirstChild("HalloweenDimension") and workspace.HalloweenDimension:FindFirstChild("SpawnedEggs")
    if hSe and hSe:FindFirstChild(areaName) then return hSe:FindFirstChild(areaName) end
    return nil
end

local function FindEgg()
    local areas = typeof(SelectedArea)=="table" and SelectedArea or {SelectedArea}
    if #SelectedRarities>0 then
        for _,prio in ipairs(SelectedRarities) do
            for _,areaName in ipairs(areas) do
                local folder = GetEggFolder(areaName)
                if folder then
                    for _,model in ipairs(folder:GetChildren()) do
                        local rarity = model:GetAttribute("Rarity")
                        if rarity and string.lower(rarity)==string.lower(prio) then
                            return model, areaName, rarity
                        end
                    end
                end
            end
        end
        return nil
    else
        for _,areaName in ipairs(areas) do
            local folder = GetEggFolder(areaName)
            if folder then
                for _,model in ipairs(folder:GetChildren()) do
                    local rarity = model:GetAttribute("Rarity")
                    if rarity then
                        return model, areaName, rarity
                    end
                end
            end
        end
        return nil
    end
end

local function TweenToPos(hrp, targetPos)
    if not hrp then return end
    local speed = _G.TweenSpeed or 16
    if speed<1 then speed=1 end
    local dur = math.clamp((hrp.Position-targetPos).Magnitude/speed,0.1,20)
    local cfVal = Instance.new("CFrameValue") cfVal.Value=hrp.CFrame
    local conn = RS.Heartbeat:Connect(function() pcall(function() hrp.CFrame=cfVal.Value end) end)
    local tw = TS:Create(cfVal, TweenInfo.new(dur, Enum.EasingStyle.Linear), {Value=CFrame.new(targetPos)})
    tw:Play() tw.Completed:Wait()
    conn:Disconnect() cfVal:Destroy()
end

local function TweenTo(targetPos)
    local hrp = GetHRP()
    if not hrp then return end
    local hum = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")
    if hum then hum.PlatformStand=true hum.AutoRotate=false end
    TweenToPos(hrp, targetPos)
    if hum then hum.PlatformStand=false hum.AutoRotate=true end
end

local function getRarityFromModel(m) local r=m:GetAttribute("Rarity") if r~=nil then return tostring(r) end r=m:GetAttribute("rarity") if r~=nil then return tostring(r) end return nil end
local function getModelPos(m) if m.PrimaryPart then return m.PrimaryPart.CFrame end local ok,cf=pcall(function() return m:GetPivot() end) if ok then return cf end local p=m:FindFirstChildWhichIsA("BasePart",true) if p then return p.CFrame end return CFrame.new() end
local function getEggInfo(m)
    local a=m:GetAttributes()
    local rarity = a.Rarity or a.rarity or getRarityFromModel(m) or "?"
    local weightRaw = a.WeightKg or a.Weight or a.KG or 0
    local weightStr = "-"
    if typeof(weightRaw)=="number" then weightStr=string.format("%.2f Kg",weightRaw) elseif weightRaw~=0 then weightStr=tostring(weightRaw).." Kg" end
    return tostring(rarity), tostring(weightStr)
end

local MainTab = Window:Tab({Title="Main", Icon="M"})
local GuardTab = Window:Tab({Title="Guard", Icon="G"})
local EventTab = Window:Tab({Title="Event", Icon="E"})

local GuardAcc = GuardTab:Accordion({Title="Guard", Open=true})
GuardAcc:Toggle({
    Title="Anti Guard",
    Flag="AntiGuard",
    Default=false,
    Callback=function(v)
        AntiGuardEnabled=v
        if v then
            if hookmetamethod then
                OldNamecall=hookmetamethod(game,"__namecall",function(self,...)
                    if AntiGuardEnabled and getnamecallmethod()=="InvokeServer" and (self==GuardRF or tostring(self)=="Capture") then return nil end
                    return OldNamecall(self,...)
                end)
            end
            if hookfunction and GuardRF then OldInvoke=hookfunction(GuardRF.InvokeServer,function() return nil end) end
        else
            if OldNamecall then pcall(function() hookmetamethod(game,"__namecall",OldNamecall) end) end
            if OldInvoke and GuardRF then pcall(function() hookfunction(GuardRF.InvokeServer,OldInvoke) end) end
        end
    end
})

local StealAcc = MainTab:Accordion({Title="Steal", Open=true})
StealAcc:Dropdown({Title="Rarity", Flag="Rarity", Options=RarityList, Default={}, Multi=true, Callback=function(v) SelectedRarities=v end})
StealAcc:Dropdown({Title="Area", Flag="Area", Options=IslandList, Default=IslandList[1], Multi=true, Callback=function(v) SelectedArea=v end})
StealAcc:Dropdown({Title="Mode", Flag="Mode", Options={"Normal","Silent"}, Default="Normal", Callback=function(v) StealMode=v end})
local TweenSlider = StealAcc:Slider({Title="Speed", Flag="Speed", Min=1, Max=1000, Step=1, Default=16, Suffix=" studs/s", Callback=function(v) _G.TweenSpeed=v end})

StealAcc:Button({Title="Check Speed", Callback=function()
    task.spawn(function()
        local char=plr.Character
        local hrp=GetHRP()
        local hum=char and char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end
        local originalCF=hrp.CFrame
        local target
        pcall(function() target=workspace.Structures:GetChildren()[9]:GetChildren()[2]:GetChildren()[22] end)
        if not target then return end
        local targetPos
        if target:IsA("BasePart") then targetPos=target.Position
        elseif target:IsA("Model") then targetPos=target:GetPivot().Position
        else local bp=target:FindFirstChildWhichIsA("BasePart",true) if bp then targetPos=bp.Position end end
        if not targetPos then return end
        local startY=hrp.Position.Y
        hum:MoveTo(targetPos)
        local t0=tick()
        repeat
            task.wait(0.05)
            local curY=hrp.Position.Y
            if curY>startY+0.5 then
                local ws=hum.WalkSpeed
                _G.TweenSpeed=math.clamp(math.floor(ws),1,1000)
                pcall(function() if TweenSlider.Set then TweenSlider:Set(ws) end end)
                Window.Notify("Speed", tostring(_G.TweenSpeed), Color3.fromRGB(74,222,128), 2)
                break
            end
            if (hrp.Position-targetPos).Magnitude<3 then break end
        until tick()-t0>15
        task.wait(0.5)
        hrp.CFrame=originalCF
    end)
end})

StealAcc:Toggle({Title="Auto Steal", Flag="AutoSteal", Default=false, Callback=function(v)
    AutoSteal=v
    if v then task.spawn(function()
        while AutoSteal do
            local egg,area,rarity=FindEgg()
            if not egg or not egg.Parent then task.wait(0.8)
            else
                Window.Notify(egg.Name, area.." | "..rarity, Color3.fromRGB(56,200,255), 2)
                local eggPos=egg:GetPivot().Position
                local yAligned=V3(STAGE_POS.X, eggPos.Y, STAGE_POS.Z)
                if StealMode=="Silent" then
                    local realChar=plr.Character
                    local realHRP=GetHRP()
                    local realHum=realChar and realChar:FindFirstChildOfClass("Humanoid")
                    if not realHRP then task.wait(0.5) continue end
                    local originalCF=realHRP.CFrame
                    local originalCamSub=workspace.CurrentCamera.CameraSubject
                    realChar.Archivable=true
                    local clone=realChar:Clone()
                    clone.Name="SilentDecoy"
                    clone.Parent=workspace
                    for _,p in ipairs(clone:GetDescendants()) do if p:IsA("Script") or p:IsA("LocalScript") then p:Destroy() end end
                    local cloneHRP=clone:FindFirstChild("HumanoidRootPart")
                    local cloneHum=clone:FindFirstChildOfClass("Humanoid")
                    if cloneHRP then cloneHRP.CFrame=originalCF cloneHRP.Anchored=true end
                    if cloneHum then cloneHum.PlatformStand=true end
                    workspace.CurrentCamera.CameraSubject=cloneHum
                    for _,p in ipairs(realChar:GetDescendants()) do if p:IsA("BasePart") and p.Name~="HumanoidRootPart" then p.Transparency=1 end end
                    TweenTo(yAligned)
                    TweenTo(eggPos+V3(0,1,0))
                    repeat if not AutoSteal then break end FireInteract(egg) task.wait(0.2) until IsDropOn() or not AutoSteal
                    if IsDropOn() and AutoSteal then
                        TweenTo(yAligned)
                        repeat task.wait(0.5) until not IsDropOn() or not AutoSteal
                    end
                    if realHRP then realHRP.CFrame=originalCF end
                    for _,p in ipairs(realChar:GetDescendants()) do if p:IsA("BasePart") then p.Transparency=0 end end
                    if clone then clone:Destroy() end
                    workspace.CurrentCamera.CameraSubject=originalCamSub or realHum
                else
                    local hrp=GetHRP()
                    if hrp then hrp.CFrame=CFrame.new(STAGE_POS) end task.wait(0.15)
                    TweenTo(yAligned)
                    TweenTo(eggPos+V3(0,1,0))
                    repeat if not AutoSteal then break end FireInteract(egg) task.wait(0.2) until IsDropOn() or not AutoSteal
                    if IsDropOn() and AutoSteal then
                        TweenTo(yAligned)
                        repeat task.wait(0.5) until not IsDropOn() or not AutoSteal
                    end
                end
            end
            task.wait(0.2)
        end
    end) end
end})

local TreadAcc = MainTab:Accordion({Title="Treadmill", Open=true})
local AutoClickX2, ChildAddedConn = false, nil
local function HasNumber(s) return s:match("%d")~=nil end
local function ClickWithoutMouse(b) pcall(function() if firesignal then firesignal(b.MouseButton1Click) firesignal(b.Activated) end end) pcall(function() if getconnections then for _,c in ipairs(getconnections(b.MouseButton1Click)) do c:Fire() end end end) end
TreadAcc:Toggle({Title="Auto x2", Flag="AutoX2", Default=false, Callback=function(v)
    AutoClickX2=v
    if v then
        local general = plr.PlayerGui:FindFirstChild("General")
        if not general then return end
        if ChildAddedConn then ChildAddedConn:Disconnect() end
        ChildAddedConn=general.ChildAdded:Connect(function(child)
            if not AutoClickX2 then return end
            if child:IsA("Frame") and HasNumber(child.Name) then
                task.wait(0.05)
                for _,btn in ipairs(child:GetDescendants()) do if (btn:IsA("ImageButton") or btn:IsA("TextButton")) and btn.Visible then ClickWithoutMouse(btn) end end
            end
        end)
        task.spawn(function()
            while AutoClickX2 do
                local gen=plr.PlayerGui:FindFirstChild("General")
                if gen then
                    for _,frame in ipairs(gen:GetChildren()) do
                        if frame:IsA("Frame") and frame.Visible and HasNumber(frame.Name) then
                            for _,btn in ipairs(frame:GetDescendants()) do if (btn:IsA("ImageButton") or btn:IsA("TextButton")) and btn.Visible then ClickWithoutMouse(btn) end end
                        end
                    end
                end
                task.wait(0.03)
            end
        end)
    else
        AutoClickX2=false
        if ChildAddedConn then ChildAddedConn:Disconnect() ChildAddedConn=nil end
    end
end})

-- HALLOWEEN EVENT (SEMUA DI SINI, TANPA ACCORDION TAMBAHAN)
local HalloweenAcc = EventTab:Accordion({Title="Halloween Event", Open=true})

local AttackMode = "Above"
local YOffset = 7
local AttackTimer = 60
local AutoAttackMonster = false

local function GetMonsterFolder() return workspace:FindFirstChild("HalloweenDimension") and workspace.HalloweenDimension:FindFirstChild("ActiveMiniMonsters") end
local function GetCandyFolder() return workspace:FindFirstChild("CandyDrops") or (workspace:FindFirstChild("HalloweenDimension") and workspace.HalloweenDimension:FindFirstChild("CandyDrops")) end
local function GetMonsterHealth(monster)
    local h = monster:GetAttribute("Health") if h ~= nil then return h end
    local hum = monster:FindFirstChildOfClass("Humanoid") if hum then return hum.Health end
    return 1
end
local function GetClosestMonster(hrpPos)
    local folder = GetMonsterFolder() if not folder then return nil end
    local closest, dist = nil, math.huge
    for _, m in ipairs(folder:GetChildren()) do
        if m:IsA("Model") and GetMonsterHealth(m) > 0 then
            local ok, pos = pcall(function() return m:GetPivot().Position end)
            if ok then local d = (hrpPos - pos).Magnitude if d < dist then dist = d closest = m end end
        end
    end
    return closest
end
local function EquipBatTool()
    local char = plr.Character if not char then return nil end
    local already = char:FindFirstChild("Bat") if already then return already end
    already = char:FindFirstChildWhichIsA("Tool") if already and string.lower(already.Name):find("bat") then return already end
    if already then return already end
    local backpack = plr:FindFirstChild("Backpack") if not backpack then return nil end
    for _, t in ipairs(backpack:GetChildren()) do if t:IsA("Tool") and string.lower(t.Name):find("bat") then t.Parent = char return t end end
    local any = backpack:FindFirstChildWhichIsA("Tool") if any then any.Parent = char return any end
    return nil
end

HalloweenAcc:Dropdown({Title="Attack Mode", Flag="HalloweenAttackMode", Options={"Above","Below"}, Default="Above", Callback=function(v) AttackMode = typeof(v)=="table" and (v[1] or "Above") or v end})
HalloweenAcc:Slider({Title="Y Offset", Flag="HalloweenYOffset", Min=0, Max=25, Step=1, Default=7, Suffix=" studs", Callback=function(v) YOffset=v end})
HalloweenAcc:Slider({Title="Attack Timer", Flag="HalloweenTimer", Min=10, Max=300, Step=5, Default=60, Suffix="s", Callback=function(v) AttackTimer=v end})
HalloweenAcc:Toggle({
    Title="Auto Attack Monster", Flag="HalloweenAutoAttack", Default=false,
    Callback=function(v)
        AutoAttackMonster=v
        if v then
            task.spawn(function()
                local attackStart = tick()
                while AutoAttackMonster do
                    if tick() - attackStart >= AttackTimer then
                        Window.Notify("Timer Habis", "Collecting CandyDrops...", Color3.fromRGB(255,221,87), 2)
                        local candyFolder = GetCandyFolder()
                        if candyFolder then
                            while AutoAttackMonster and #candyFolder:GetChildren() > 0 do
                                local hrp = GetHRP() if not hrp then task.wait(0.3) continue end
                                local closest, dist = nil, math.huge
                                for _, c in ipairs(candyFolder:GetChildren()) do
                                    local ok, pos = pcall(function() return c:GetPivot().Position end)
                                    if not ok then local bp = c:IsA("BasePart") and c or c:FindFirstChildWhichIsA("BasePart") if bp then pos = bp.Position ok = true end end
                                    if ok then local d = (hrp.Position - pos).Magnitude if d < dist then dist = d closest = c end end
                                end
                                if not closest then task.wait(0.3) continue end
                                local ok, cPos = pcall(function() return closest:GetPivot().Position end)
                                if not ok then local bp = closest:IsA("BasePart") and closest or closest:FindFirstChildWhichIsA("BasePart") if bp then cPos = bp.Position ok = true end end
                                if ok then
                                    hrp.CFrame = CFrame.new(cPos + V3(0, 3, 0))
                                    FireInteract(closest)
                                    pcall(function()
                                        if firetouchinterest then
                                            local part = closest:IsA("BasePart") and closest or closest:FindFirstChildWhichIsA("BasePart")
                                            if part then firetouchinterest(hrp, part, 0) task.wait(0.05) firetouchinterest(hrp, part, 1) end
                                        end
                                    end)
                                end
                                task.wait(0.12)
                            end
                        end
                        attackStart = tick()
                    end
                    local hrp = GetHRP() if not hrp then task.wait(0.3) continue end
                    local monster = GetClosestMonster(hrp.Position) if not monster or not monster.Parent then task.wait(0.5) continue end
                    local ok, mCF = pcall(function() return monster:GetPivot() end) if not ok then task.wait(0.2) continue end
                    local mPos = mCF.Position
                    local firstTarget = (AttackMode == "Above") and (mPos + V3(0, YOffset, 0)) or (mPos - V3(0, YOffset, 0))
                    hrp.CFrame = CFrame.new(firstTarget, mPos)
                    while AutoAttackMonster and monster.Parent and GetMonsterHealth(monster) > 0 do
                        if tick() - attackStart >= AttackTimer then break end
                        hrp = GetHRP() if not hrp then break end
                        local suc, curCF = pcall(function() return monster:GetPivot() end) if not suc then break end
                        local curPos = curCF.Position
                        local stickPos = (AttackMode == "Above") and (curPos + V3(0, YOffset, 0)) or (curPos - V3(0, YOffset, 0))
                        hrp.CFrame = CFrame.new(stickPos, curPos)
                        local tool = EquipBatTool()
                        if tool then pcall(function() tool:Activate() if firesignal then firesignal(tool.Activated) end if getconnections then for _, conn in ipairs(getconnections(tool.Activated)) do conn:Fire() end end end) end
                        RS.Heartbeat:Wait()
                    end
                    task.wait(0.1)
                end
            end)
        end
    end
})

-- JANGAN DI SENTUH DARI SINI KE BAWAH (VAULT PANEL)
local function setupViewport(vp, mdl) pcall(function() vp:ClearAllChildren() local clone=mdl:Clone() for _,d in ipairs(clone:GetDescendants()) do if d:IsA("Script") or d:IsA("LocalScript") then d:Destroy() end if d:IsA("BasePart") then d.Anchored=true d.CanCollide=false end end clone.Parent=vp local cam=New("Camera", {}, vp) vp.CurrentCamera=cam local cf,size=clone:GetBoundingBox() local md=math.max(size.X,size.Y,size.Z) if md<0.5 then md=4 end cam.CFrame=CFrame.new(cf.Position+V3(0, md*0.2, md*1.8), cf.Position) cam.FieldOfView=42 end) end

local VaultPanel = Window:Panel({Title="Egg Vault", Width=420, Open=false, GripY=0.35})

local function getPanelScroll()
    local function findIn(host)
        if not host then return nil end
        local gui=host:FindFirstChild("SORU_HUB")
        if not gui then return nil end
        for _,v in ipairs(gui:GetDescendants()) do
            if v.Name=="SORU_Panel" then
                local body=v:FindFirstChild("Body")
                if body then
                    for _,ch in ipairs(body:GetChildren()) do if ch:IsA("ScrollingFrame") then return ch end end
                    for _,d in ipairs(body:GetDescendants()) do if d:IsA("ScrollingFrame") then return d end end
                end
            end
        end
        return nil
    end
    local pg=plr:FindFirstChild("PlayerGui")
    local hg=nil
    pcall(function() if gethui then hg=gethui() end end)
    local t0=tick()+6
    while tick()<t0 do
        local sc=findIn(pg) or findIn(hg)
        if sc then return sc end
        task.wait(0.2)
    end
    return nil
end

task.wait(0.5)
local scroll=getPanelScroll()
local currentFilter="All"
local currentSearch=""

local countLabel=VaultPanel:Label("0 eggs")
VaultPanel:Dropdown({Title="Area", Flag="VaultArea", Options=workspace:FindFirstChild("SpawnedEggs") and (function() local l={"All"} for _,c in ipairs(workspace.SpawnedEggs:GetChildren()) do table.insert(l,c.Name) end return l end)() or {"All"}, Default="All", Callback=function(v) currentFilter=v if _G._refreshVault then _G._refreshVault() end end})
VaultPanel:Textbox({Title="Search", Placeholder="egg / rarity", Flag="VaultSearch", Live=true, Callback=function(t) currentSearch=t if _G._refreshVault then _G._refreshVault() end end})
VaultPanel:Button({Title="Refresh", Callback=function() if _G._refreshVault then _G._refreshVault() end end})
VaultPanel:Divider()

local eggContainer
if scroll then
    eggContainer=New("Frame", {Name="EggContainer", Size=UDim2.new(1,0,0,0), AutomaticSize=Enum.AutomaticSize.Y, BackgroundTransparency=1, LayoutOrder=100}, scroll)
    New("UIListLayout", {Padding=UDim.new(0,8), SortOrder=Enum.SortOrder.LayoutOrder}, eggContainer)
end

local function createEggCard(parent, mdl, areaName)
    if not parent then return end
    local rarity, weightStr = getEggInfo(mdl)
    local hold=New("Frame", {Size=UDim2.new(1,0,0,82), BackgroundTransparency=1, ClipsDescendants=true}, parent)
    local card=New("Frame", {Size=UDim2.fromScale(1,1), BackgroundColor3=Color3.fromRGB(25,22,41), BorderSizePixel=0}, hold)
    New("UICorner", {CornerRadius=UDim.new(0,12)}, card)
    New("UIStroke", {Color=Color3.fromRGB(68,61,106), Transparency=0.55, Thickness=1}, card)
    local thumb=New("Frame", {Size=UDim2.fromOffset(56,56), Position=UDim2.fromOffset(8,13), BackgroundColor3=Color3.fromRGB(13,11,23), Active=false}, card)
    New("UICorner", {CornerRadius=UDim.new(0,10)}, thumb)
    local vp=New("ViewportFrame", {Size=UDim2.fromScale(1,1), BackgroundTransparency=1, Active=false}, thumb)
    New("UICorner", {CornerRadius=UDim.new(0,10)}, vp)
    task.spawn(function() setupViewport(vp, mdl) end)
    New("TextLabel", {Text=mdl.Name, Position=UDim2.fromOffset(74,8), Size=UDim2.new(1,-84,0,18), Font=Enum.Font.GothamBold, TextSize=13, TextColor3=Color3.fromRGB(246,244,255), BackgroundTransparency=1, TextXAlignment=Enum.TextXAlignment.Left, TextTruncate=Enum.TextTruncate.AtEnd, Active=false}, card)
    New("TextLabel", {Text=rarity.." | "..areaName, Position=UDim2.fromOffset(74,26), Size=UDim2.new(1,-84,0,16), Font=Enum.Font.GothamMedium, TextSize=11, TextColor3=Color3.fromRGB(150,142,186), BackgroundTransparency=1, TextXAlignment=Enum.TextXAlignment.Left, TextTruncate=Enum.TextTruncate.AtEnd, Active=false}, card)
    New("TextLabel", {Text=weightStr, Position=UDim2.fromOffset(74,42), Size=UDim2.new(1,-84,0,16), Font=Enum.Font.GothamBold, TextSize=11, TextColor3=Color3.fromRGB(74,222,128), BackgroundTransparency=1, TextXAlignment=Enum.TextXAlignment.Left, TextTruncate=Enum.TextTruncate.AtEnd, Active=false}, card)
    local btn=New("TextButton", {Size=UDim2.fromScale(1,1), BackgroundTransparency=1, Text="", AutoButtonColor=false, ZIndex=10}, hold)
    btn.MouseButton1Click:Connect(function()
        if not mdl.Parent then Window.Notify("Vault", "gone", Color3.fromRGB(248,113,113), 1.5) return end
        task.spawn(function()
            local eggPos=getModelPos(mdl).Position
            local yAligned=V3(STAGE_POS.X, eggPos.Y, STAGE_POS.Z)
            Window.Notify(mdl.Name, areaName.." | "..rarity, Color3.fromRGB(56,200,255), 2)
            TweenTo(yAligned)
            TweenTo(eggPos+V3(0,1,0))
            repeat FireInteract(mdl) task.wait(0.2) until IsDropOn() or not mdl.Parent
            if IsDropOn() then
                TweenTo(yAligned)
                repeat task.wait(0.5) until not IsDropOn()
            end
        end)
    end)
end

local function getAllVaultModels()
    local sp=workspace:FindFirstChild("SpawnedEggs")
    if not sp then return {} end
    local list={}
    local toScan={}
    if currentFilter and currentFilter~="All" then local t=sp:FindFirstChild(currentFilter) if t then toScan={t} end else toScan=sp:GetChildren() end
    for _,folder in ipairs(toScan) do
        if folder:IsA("Folder") or folder:IsA("Model") then
            for _,mdl in ipairs(folder:GetChildren()) do if mdl:IsA("Model") then table.insert(list,{mdl=mdl, area=folder.Name}) end end
        end
    end
    if currentSearch and currentSearch~="" then
        local q=string.lower(currentSearch)
        local f2={}
        for _,it in ipairs(list) do local rar=getRarityFromModel(it.mdl) or "" if string.lower(it.mdl.Name):find(q,1,true) or string.lower(rar):find(q,1,true) then table.insert(f2,it) end end
        list=f2
    end
    return list
end

local function refreshVault()
    if not eggContainer then
        local sc=getPanelScroll()
        if sc then
            eggContainer=New("Frame", {Name="EggContainer", Size=UDim2.new(1,0,0,0), AutomaticSize=Enum.AutomaticSize.Y, BackgroundTransparency=1, LayoutOrder=100}, sc)
            New("UIListLayout", {Padding=UDim.new(0,8), SortOrder=Enum.SortOrder.LayoutOrder}, eggContainer)
        else return end
    end
    for _,c in ipairs(eggContainer:GetChildren()) do if c:IsA("Frame") then c:Destroy() end end
    local models=getAllVaultModels()
    countLabel:Set(#models.." eggs")
    VaultPanel:SetTitle("Egg Vault ("..#models..")")
    for _,it in ipairs(models) do if it.mdl.Parent then createEggCard(eggContainer,it.mdl,it.area) end end
end
_G._refreshVault=refreshVault

local PanelTab=Window:Tab({Title="Panel", Icon="P"})
PanelTab:Button({Title="Open Vault", Callback=function() VaultPanel:Show() task.wait(0.2) refreshVault() end})
PanelTab:Button({Title="Close Vault", Callback=function() VaultPanel:Hide() end})

task.spawn(function() while task.wait(3) do if VaultPanel:IsOpen() then pcall(refreshVault) end end end)
